parameters.jsCode:
const u = $input.all()[0].json;
if (!u.unread || u.unread.length === 0) return [{ json: { skip: true, reason: 'No unread notifications' } }];
// Group by category
const groups = {};
for (const n of u.unread) {
  const cat = n.category || n.type || 'General';
  if (!groups[cat]) groups[cat] = [];
  groups[cat].push(n);
}
const sectionsHtml = Object.entries(groups).map(([cat, items]) => {
  const itemsHtml = items.slice(0, 5).map(i => `<li style="padding:4px 0;">${i.title}${i.body ? ': ' + i.body.slice(0, 120) : ''}</li>`).join('');
  const more = items.length > 5 ? `<li style="color:#6b7280;font-size:12px;">+${items.length - 5} more in ${cat}</li>` : '';
  return `<h3 style="color:#9a3412;margin-top:16px;">${cat} (${items.length})</h3><ul>${itemsHtml}${more}</ul>`;
}).join('');
const totalCount = u.unread.length;
const html = `
<!doctype html><html><body style="font-family:Arial,Helvetica,sans-serif;color:#1f2937;background:#fff7ed;margin:0;padding:0;">
  <div style="max-width:600px;margin:0 auto;padding:32px;">
    <h1 style="color:#ea580c;">Your Dayjoy Daily Digest 📬</h1>
    <p>Hi ${u.userName || 'there'},</p>
    <p>You have <strong>${totalCount} unread notification${totalCount !== 1 ? 's' : ''}</strong> from the last 24 hours.</p>
    ${sectionsHtml}
    <p style="margin-top:24px;"><a href="https://app.dayjoy.in/notifications" style="background:#ea580c;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none;display:inline-block;">View All Notifications →</a></p>
    <hr style="margin:24px 0;border:none;border-top:1px solid #fed7aa;" />
    <p style="font-size:12px;color:#6b7280;">Dayjoy Wellness Pvt. Ltd. · notifications@dayjoy.in</p>
  </div>
</body></html>`;
return [{ json: { skip: false, html, subject: `Dayjoy Daily Digest — ${totalCount} notification${totalCount !== 1 ? 's' : ''}`, recipientEmail: u.email, userId: u.userId, tenantId: u.tenantId, notificationIds: u.unread.map(n => n.id) } }];

